-- Researcher-verified LinkedIn numerics for the Serbia census firms,
-- ingested from the user-supplied sheet (2026-08-13). 71 firms; every
-- row was live-confirmed on the firm's public LinkedIn company page by
-- the user (rows marked 'No Page'/'N/A' were excluded — the peer pool
-- must never see estimated numerics). Consumed by runVisibilityAudit's
-- social leg (source "directory") when the firm didn't self-report.
--
-- Value shape: {"followers":N,"posts30d":N,"url":<company page>,"verifiedAt":"2026-08-13"}

ALTER TABLE public.market_directory_data ADD COLUMN IF NOT EXISTS linkedin jsonb NOT NULL DEFAULT '{}'::jsonb;

